`timescale 1ns / 1ps
//=============================================================================
// tb_sound_engine.v : A's DDS voice produces the right pitch
//   Plays A4 (MIDI 69, 440 Hz) and C5 (523.25 Hz) and counts square-wave
//   cycles over 1 s of samples (48 828 sample ticks). Tick_sample is
//   generated by the testbench every 4 clocks so the run is short; the DDS
//   only counts ticks, so the pitch per tick is the same as on the board.
//   Also checks: mute gives silence (128), sample stays inside 0..255 swing.
//=============================================================================
module tb_sound_engine;
    reg clk = 0, rst = 1, ts = 0, t1 = 0, ev = 0, mute = 0;
    reg [6:0] note = 0;
    wire [7:0] sample, scope;
    wire [3:0] va;
    sound_engine dut (.clk(clk), .rst(rst), .tick_sample(ts), .tick_1ms(t1), .ev_valid(ev),
        .ev_note(note), .ev_vel(2'd2), .sfx_valid(1'b0), .sfx_id(4'd0),
        .settings(16'b0000_11_0_0_1_01_111_00), .mute(mute),
        .sample(sample), .scope_sample(scope), .voice_active(va));
    always #5 clk = ~clk;

    integer cycles, n, errors = 0;
    reg prev_hi;
    task measure; input [6:0] nn; input integer f_expect;
        begin
            @(posedge clk) begin note <= nn; ev <= 1; end
            @(posedge clk) ev <= 0;
            cycles = 0; prev_hi = 0;
            // 48828 sample ticks = 1 s of audio; keep the envelope alive by
            // never sending tick_1ms (decay is per ms)
            for (n = 0; n < 48828; n = n + 1) begin
                repeat (3) @(posedge clk);
                @(posedge clk) ts <= 1; @(posedge clk) ts <= 0;
                @(posedge clk);
                if (sample > 8'd128 && !prev_hi) cycles = cycles + 1;
                prev_hi = (sample > 8'd128);
            end
            if (cycles >= f_expect - 1 && cycles <= f_expect + 1)
                $display("PASS note %0d: %0d cycles in 1 s (expect %0d)", nn, cycles, f_expect);
            else begin
                $display("FAIL note %0d: %0d cycles in 1 s (expect %0d)", nn, cycles, f_expect);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        repeat (3) @(posedge clk); rst = 0;
        measure(7'd69, 440);
        measure(7'd72, 523);
        mute = 1;
        repeat (20) begin repeat (3) @(posedge clk); @(posedge clk) ts <= 1; @(posedge clk) ts <= 0; end
        @(posedge clk);
        if (sample == 8'd128) $display("PASS mute gives silence");
        else begin $display("FAIL mute: sample %0d", sample); errors = errors + 1; end
        if (errors == 0) $display("PASS tb_sound_engine: all checks");
        else             $display("FAIL tb_sound_engine: %0d errors", errors);
        $finish;
    end
endmodule
